[trp_xiao|auto_proceed,"start",[
  (check_quest_active, "qst_wlodowiecus_adventure_4"),
  (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_current_state, 10),
],"Hey {playername}.",
"wlodowiecus_4_kashar_wlod_talk_1",[
]],

[anyone|other(trp_xiao),"wlodowiecus_4_kashar_wlod_talk_1",[
],"-- He speaks in broken Greek --^^Greetings, stranger! Are you the one who led the group which caused so much havoc on the Great Wall? Forgive my broken Greek, I hope you can understand me? I am Lei Li, a prestigious merchant, adventurer and investor, known to all mercantile communities from Parthia to the great wall!",
"wlodowiecus_4_kashar_wlod_talk_2",[
  (call_script, "script_set_conversation_troop", "trp_xiao"),
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_2",[
],"Salve Lei Li, My name is {playername}. I am one of the expedition leaders!",
"wlodowiecus_4_kashar_wlod_talk_3",[
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_2",[
],"Greetings great merchant! I am {playername}, famous adventurer and expedition leader.",
"wlodowiecus_4_kashar_wlod_talk_3",[
]],
[anyone|other(trp_xiao),"wlodowiecus_4_kashar_wlod_talk_3",[
    (try_begin),
      (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_target_faction, 1),
      (str_store_string, s11, "@I heard you even looted the fortress Jilu and escaped right before reinforcements arrived."),
    (else_try),
      (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_target_faction, 2),
      (str_store_string, s11, "@I heard you spared the fortress Jilu but imprisoned their commander inside his own prison!"),
    (try_end),
],"{playername}, news of a group of adventurers from the west traveling through Sogdiana has reached my ears and I followed your progress, but suddenly there's no more trace of you so I figure you all died. But then I hear how somehow a captain responsible for a small section in the wall almost lost his life due to a clash with those very same adventurers. {s11} This intrigued me. Oh! I haven't introduced my associate, she is Eamane. Anyways, I just so happen to represent the silk merchants of Chang'an, the capital city of Zhonguo, the magnanimous city which, sadly, you likely will never see, for obvious reasons.",
"wlodowiecus_4_kashar_wlod_talk_4",[
  (call_script, "script_set_conversation_troop", "trp_xiao"),
]],
[anyone|other(trp_xiao),"wlodowiecus_4_kashar_wlod_talk_4",[
],"I am nevertheless very much interested in opening a trade route to the distant Empire of yours. I have an offer for you. I want you to escort me and Eamane to this Empire of yours, to establish contacts. I will open a shop in Rome, offering Chinese silk, many luxuries and, what I assume will interest you the most, also weaponry, armor and beautifully crafted goods, allowing people to buy those things. Would be quite a sight. In addition, I will help you finish your contract by signing a deal with this Libyan sponsor of yours. How do I know of him? Heh, someone in my position must keep some secrets, don't you agree? Anyways, as gift I also offer you my father's old sword, the gilded jian from times when he himself was an officer in Imperial service and for Eamane to join your party as a companion. She is a bright and hardworking woman, not ashamed of battle which I believe will serve your needs well. She's been nagging me for quite some time to change our routes or involve ourselves in some local dispute. I'm afraid that I'll bore the poor girl to death. So what say you Emamne?",
"wlodowiecus_4_kashar_wlod_talk_5",[
  (call_script, "script_set_conversation_troop", "trp_xiao"),
]],
[anyone|other(trp_turakina),"wlodowiecus_4_kashar_wlod_talk_5",[
],"-- She also speaks in broken Greek. --^^Yes. I like that.",
"wlodowiecus_4_kashar_wlod_talk_6",[
  (call_script, "script_set_conversation_troop", "trp_turakina"),
]],
[anyone|other(trp_xiao),"wlodowiecus_4_kashar_wlod_talk_6",[
],"Yes, yes. I bet this is the best offer you've ever received, no? I certainly never saw anyone offer adventures anything better. And if they did? It was all lies and those fools got sent to their deaths.",
"wlodowiecus_4_kashar_wlod_talk_7",[
  (call_script, "script_set_conversation_troop", "trp_xiao"),
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_7",[
],"That's unexpected! I agree to all of it.",
"wlodowiecus_4_kashar_wlod_talk_8",[
  (call_script, "script_change_player_relation_with_troop", "trp_xiao", 50),
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_7",[
],"Great news. I accepct your offer and your gifts!",
"wlodowiecus_4_kashar_wlod_talk_8",[
  (call_script, "script_change_player_relation_with_troop", "trp_xiao", 50),
]],
[anyone|other(trp_xiao),"wlodowiecus_4_kashar_wlod_talk_8",[
],"I think I can help you with that. I heard the Parthian caravan master named Phamanus is resting here with his caravan, waiting on route to return back to his homeland. I can bring you to him, so we can arrange the way back to your homeland. We'll have a lot to talk about on the way.",
"wlodowiecus_4_kashar_wlod_talk_9",[
  (call_script, "script_set_conversation_troop", "trp_xiao"),
]],
[anyone|other(trp_wlodowiecus),"wlodowiecus_4_kashar_wlod_talk_9",[
],"Perfect. I can't wait to get out of this lands.",
"wlodowiecus_4_kashar_wlod_talk_10",[
  (call_script, "script_set_conversation_troop", "trp_wlodowiecus"),
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_10",[
],"To be honet I will miss this lands.",
"wlodowiecus_4_kashar_wlod_talk_11_1",[
  (call_script, "script_set_conversation_troop", "trp_wlodowiecus"),
]],
[anyone|plyr,"wlodowiecus_4_kashar_wlod_talk_10",[
],"Nothing is better than the own hearth fire.",
"wlodowiecus_4_kashar_wlod_talk_11_2",[
  (call_script, "script_set_conversation_troop", "trp_wlodowiecus"),
]],
[anyone|other(trp_wlodowiecus),"wlodowiecus_4_kashar_wlod_talk_11_1",[
],"I totally agree {playername}! Now let'ss get ready for the journey home.",
"close_window",[
  (call_script, "script_set_conversation_troop", "trp_wlodowiecus"),
  (jump_to_menu, "mnu_wlodowiecus_adventure_1_4_journey_end_2"),
  (mission_disable_talk),
  (mission_cam_animate_to_screen_color, 0xFF000000, 7000),
  (finish_mission, 8),
]],
[anyone|other(trp_wlodowiecus),"wlodowiecus_4_kashar_wlod_talk_11_2",[
],"I totally disagree {playername}, this lands are terrible. Far too wide, way too cruel, even for me, and almost no trees and too much desert and too much steppe. Now let'ss get ready for the journey home.",
"close_window",[
  (call_script, "script_set_conversation_troop", "trp_wlodowiecus"),
  (jump_to_menu, "mnu_wlodowiecus_adventure_1_4_journey_end_2"),
  (mission_disable_talk),
  (mission_cam_animate_to_screen_color, 0xFF000000, 7000),
  (finish_mission, 8),
]],

[trp_mancinellus,"start",[
  (check_quest_active, "qst_wlodowiecus_adventure_4"),
  (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_current_state, 10),
  (agent_slot_eq, "$g_talk_agent", slot_agent_already_begg, 1),
],"I think Wlodowiecus wants to talk with you.",
"close_window",[
]],
[trp_mancinellus,"start",[
  (check_quest_active, "qst_wlodowiecus_adventure_4"),
  (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_current_state, 10),
  (agent_slot_eq, "$g_talk_agent", slot_agent_already_begg, 0),
],"You know {playername}, we've done what few Romans have ever done. We arrived at the limes of Serica. One of the best guarded borders in the world. Only very few among us have seen it or even heard of it.",
"wlodowiecus_4_kashar_manc_talk_1",[
  (agent_set_slot, "$g_talk_agent", slot_agent_already_begg, 1),
]],
[anyone|plyr,"wlodowiecus_4_kashar_manc_talk_1",[
],"Yet, we have not seen the supposedly Heavenly kingdom.",
"wlodowiecus_4_kashar_manc_talk_2",[
]],
[anyone|plyr,"wlodowiecus_4_kashar_manc_talk_1",[
],"Yet the expedition was a failure.",
"wlodowiecus_4_kashar_manc_talk_2",[
]],
[anyone|plyr,"wlodowiecus_4_kashar_manc_talk_2",[
],"It's bad but could be worse. We get so close, then we fail or so we think, we almost die and then as if this was the Iliad, the divine intervention comes and we somehow make it. I'm getting used to this by now, a little.",
"wlodowiecus_4_kashar_manc_talk_3",[
]],
[anyone,"wlodowiecus_4_kashar_manc_talk_3",[
],"Sadly true, but let us hope someday we will see Serica for what it really is. Oh the girls, the women and hehe other pleasures. Imagine what it would be like... I think I'll have a lot of pleasant dreams in the coming nights, if Wlodowiecus doesn't slit my throat. ",
"close_window",[
]],

