[trp_antonia,"start",[
  (check_quest_active, "qst_four_emperors"),
  (quest_slot_eq, "qst_four_emperors", slot_quest_current_state, 7),
  (eq, "$current_town", "p_town_6"),

  (quest_get_slot, ":goy", "qst_four_emperors", slot_quest_target_troop),
  (this_or_next|eq, ":goy", "trp_senator_2"),# otho
  (eq, ":goy", "trp_statthalter_9"), #vitellius
  (troop_get_slot, ":leaded_party", ":goy", slot_troop_leaded_party),
  (neg|party_is_active, ":leaded_party"),
  (str_store_troop_name, s10, ":goy"),
],
"{s10} has not reached Roma yet. As it seems, his party got defeated. We have to wait for him.",
"close_window",[]],

[trp_antonia,"start",[
  (check_quest_active, "qst_four_emperors"),
  (quest_slot_eq, "qst_four_emperors", slot_quest_current_state, 7),
  (eq, "$current_town", "p_town_6"),

  (quest_get_slot, ":goy", "qst_four_emperors", slot_quest_target_troop),
  (this_or_next|eq, ":goy", "trp_senator_2"),# otho
  (eq, ":goy", "trp_statthalter_9"), #vitellius
  (troop_get_slot, ":leaded_party", ":goy", slot_troop_leaded_party),
  (party_is_active, ":leaded_party"),

  (party_get_attached_to, ":attached_party_no", ":leaded_party"),
  (neq, ":attached_party_no", "p_town_6"),

  (str_store_troop_name, s10, ":goy"),
],
"{s10} has not reached Roma yet, but he is on his way. We have to wait for him.",
"close_window",[]],

[trp_senator_2 ,"start",[
  (check_quest_active, "qst_four_emperors"),
  (quest_slot_eq, "qst_four_emperors", slot_quest_current_state, 7),
  (eq, "$current_town", "p_town_6"),

  (quest_get_slot, ":goy", "qst_four_emperors", slot_quest_target_troop),
  (this_or_next|eq, ":goy", "trp_senator_2"),# otho
  (eq, ":goy", "trp_statthalter_9"), #vitellius
  (troop_get_slot, ":leaded_party", ":goy", slot_troop_leaded_party),
  (party_is_active, ":leaded_party"),
  (party_get_attached_to, ":attached_party_no", ":leaded_party"),
  (eq, ":attached_party_no", "p_town_6"),
],"We are waiting for you for ages. I am starving! Now, talk with Antonia so that we can finally enter and have some food!",
"close_window",[]],

[trp_statthalter_9 ,"start",[
  (check_quest_active, "qst_four_emperors"),
  (quest_slot_eq, "qst_four_emperors", slot_quest_current_state, 7),
  (eq, "$current_town", "p_town_6"),

  (quest_get_slot, ":goy", "qst_four_emperors", slot_quest_target_troop),
  (this_or_next|eq, ":goy", "trp_senator_2"),# otho
  (eq, ":goy", "trp_statthalter_9"), #vitellius
  (troop_get_slot, ":leaded_party", ":goy", slot_troop_leaded_party),
  (party_is_active, ":leaded_party"),

  (party_get_attached_to, ":attached_party_no", ":leaded_party"),
  (eq, ":attached_party_no", "p_town_6"),

],"I am looking forward to finally get rid of Nero! Now, talk with Antonia!",
"close_window",[]],

[trp_antonia,"start",[
  (check_quest_active, "qst_four_emperors"),
  (quest_slot_eq, "qst_four_emperors", slot_quest_current_state, 7),
  (eq, "$current_town", "p_town_6"),

  (quest_get_slot, ":goy", "qst_four_emperors", slot_quest_target_troop),
  (this_or_next|eq, ":goy", "trp_senator_2"),# otho
  (eq, ":goy", "trp_statthalter_9"), #vitellius
  (troop_get_slot, ":leaded_party", ":goy", slot_troop_leaded_party),
  (party_is_active, ":leaded_party"),

  (party_get_attached_to, ":attached_party_no", ":leaded_party"),
  (eq, ":attached_party_no", "p_town_6"),
],"You finally arrived! Now all we need to do is enter the palace. The Praetorians are eagerly awaiting a signal! I am so excited.^^"
+"[Hints: You will have multiple options to decide the outcome of the following events:^1. You can marry Antonia.^2. Side with Poppaea.^3. Or stab Antonia at the final dialogue.^^Save before you continue and try different choices if you don't like the outcome.]",
"goy_front_of_domus_augusti_1",[]],

[anyone|plyr,"goy_front_of_domus_augusti_1",[
]," Let's enter!",
"goy_front_of_domus_augusti_2",[
  (quest_set_slot, "qst_four_emperors", slot_quest_current_state, 8),
]],

