[anyone, "start", [
    (this_or_next|eq, "$g_talk_troop", "trp_centurio_preatoriani"),
    (eq, "$g_talk_troop", "trp_centurio_west"),
    (eq, "$talk_context", tc_promotion_optio),
    (neg|quest_slot_ge, "qst_freelancing", slot_quest_freelancer_pretorian, 1), # Prevents re-offering Praetorian if already joined/attempted
],
"Ah, {playername}. Excellent timing. Your performance has been exemplary, and I'm pleased to inform you that you've earned a promotion to a junior officer rank."
+" Specifically, I have an opening for an Optio within our ranks, a position you are well-suited for. However, I also have connections within the Praetorian Guard."
+" If you're ambitious, I could put in a word to help you join them, though it would mean starting over. Candidly, I'd prefer you stay and continue your fine work here, but the choice is yours.",
"promotion_options_initial_talk",[]],

[anyone|plyr, "promotion_options_initial_talk", [
],"The Praetorian Guard sounds like a prestigious opportunity. Tell me more.",
"promotion_praetorian_details",[]],

[anyone|plyr, "promotion_options_initial_talk", [
],"Serving as an Optio here sounds like a fine advancement. I'm interested.",
"promotion_confirm_optio",[]], # Direct jump to Optio confirmation

[anyone, "promotion_praetorian_details", [
],"Indeed it is. But be warned: if you join the Guard, you'll enter as a Probatus – effectively a recruit. You'd need to prove yourself and climb the ranks anew."
+" It's a challenging path, and not many succeed. However, the prestige and influence are undeniable, that's for sure.",
"promotion_praetorian_decision_point",[]],

[anyone|plyr, "promotion_praetorian_decision_point", [
],"I understand the risks. I'd like to take the chance and ask for your assistance in joining the Guard.",
"promotion_praetorian_fee_discussion",[]],

[anyone|plyr, "promotion_praetorian_decision_point", [
],"Hmm, starting over is a significant commitment. I believe I'd rather accept the Optio position here.",
"promotion_confirm_optio",[]], # Player opts for Optio after hearing details

[anyone, "promotion_praetorian_fee_discussion", [
],"Very well, {playername}. It's a bold choice. Before I can forward your recommendation, there's a customary 'administrative fee' required to process your enlistment with the Guard - 1,000 denarii, to be precise.",
"promotion_praetorian_payment_options",[]],

[anyone|plyr, "promotion_praetorian_payment_options", [
    (store_troop_gold, ":player_gold", "trp_player"),
    (ge, ":player_gold", 1000),
],"Understood. Here is the 1,000 denarii.",
"promotion_praetorian_accepted", [
    (troop_remove_gold, "trp_player", 1000),
]],

[anyone|plyr, "promotion_praetorian_payment_options", [
],"I'm afraid I don't have that amount right now.",
"promotion_praetorian_cannot_pay",[]],

[anyone, "promotion_praetorian_cannot_pay", [
],"Unfortunate. Without the fee, my hands are tied regarding the Guard. In that case, the Optio position is still yours, and frankly, I'm glad to keep a soldier of your caliber."
+" You'll serve us well here. Now, prepare for your new responsibilities, Optio!", # Changed to be more fitting for a new officer
"close_window", [
    (jump_to_menu, "mnu_world_map_soldier"), # Or a menu that reflects their new rank
]],

[anyone, "promotion_praetorian_accepted", [
],"Excellent, {playername}. It pains me to lose such a capable soldier, but I have no doubt you have the potential to achieve great things in the Praetorian Guard. I wish you the best of luck; it will be a true test of your mettle."
+" I shall write your letter of recommendation immediately. Take it to one of the Praetorian Prefects in the major cities – they will see to your enlistment.",
"close_window", [
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_pretorian, 1),   # Mark as joining Praetorians
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_rank, 1),        # Set rank to Probatus (or equivalent ID)
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_progress, 0),
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_service_length, 0),
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_progress_limit, 100),
    (quest_set_slot, "qst_freelancing", slot_quest_freelancer_state, 2),
    (call_script, "script_end_freelancing"), # Ends current freelance contract to join Praetorians
    (assign, "$g_leave_encounter", 1),
    (jump_to_menu, "mnu_auto_return_map"),
]],

