[anyone, "commander_barracks_found_custom_unit",[
],"Very well. Follow me and we will proceed together.",
"close_window",[
  (try_begin),
      (main_party_has_troop, "$temp_troop"),
      (party_remove_members, "p_main_party", "$temp_troop", 1),
  (try_end),

  # (faction_get_slot, ":no_faction_banner", "$players_kingdom", slot_faction_banner),
  # (val_sub, ":no_faction_banner", banner_meshes_begin),
  # (store_add, ":selected_banner", ":no_faction_banner", banner_scene_props_begin),
  # (troop_set_slot, "$temp_troop", slot_troop_banner_scene_prop, ":selected_banner"),
  (call_script, "script_set_troop_banner_according_to_faction", "$temp_troop", "$players_kingdom"),

  (troop_set_slot, "$temp_troop", slot_troop_occupation, slto_kingdom_hero),
  (troop_set_slot, "$temp_troop", slot_troop_playerparty_history, dplmc_pp_history_granted_fief),

  (troop_set_faction, "$temp_troop", "$players_kingdom"),

  (troop_set_slot, "$temp_troop", slot_troop_original_faction, "$players_kingdom"),

  (store_character_level, ":renown", "$temp_troop"),
  (val_mul, ":renown", 5),
  (call_script, "script_change_troop_renown", "$temp_troop", ":renown"),

  (troop_get_slot, ":initial_wealth", "$temp_troop", slot_troop_wealth),
  (val_add, ":initial_wealth", 50000),

  (store_troop_gold, ":initial_gold", "$temp_troop"),
  (val_add, ":initial_gold", ":initial_wealth"),

  (store_skill_level, ":modifier", "skl_trade", "$temp_troop"),
  (store_skill_level, ":skill_level", "skl_looting", "$temp_troop"),
  (val_add, ":modifier", ":skill_level"),
  (val_mul, ":modifier", 100),
  (val_add, ":initial_gold", ":modifier"),

  (troop_set_slot, "$temp_troop", slot_troop_wealth, ":initial_gold"), #represents accumulated loot

  (call_script, "script_dplmc_npc_morale", "$temp_troop", 0), #just get the number
  (assign, ":relation_boost", reg0),
  (try_begin),
      (eq, "$temp", 1),
      (troop_remove_gold, "trp_player", 150000),
      (troop_set_slot, "trp_players_legion", 1, 1),##legion is created
      (assign, "$g_player_troop", "trp_players_legion"),
      (display_log_message, "@You founded your own legion!", color_good_news),
      (val_mul, ":relation_boost", 3),
      (val_div, ":relation_boost", 2),
      (call_script, "script_change_player_relation_with_troop", "$temp_troop", ":relation_boost"),

      (faction_get_slot, ":leader", "$players_kingdom", slot_faction_leader),

      (assign, ":malus", -50),

      (try_begin),
          (lt, "$player_honor", -50),
          (assign, ":malus", -70),
      (else_try),
          (lt, "$player_honor", -25),
          (assign, ":malus", -60),
      (else_try),
          (gt, "$player_honor", 50),
          (assign, ":malus", -30),
      (else_try),
          (gt, "$player_honor", 25),
          (assign, ":malus", -40),
      (try_end),

      (call_script, "script_change_player_relation_with_troop", ":leader", ":malus"),

      (store_add, ":slot", slot_legion_home_begin, 13),#player legion
      (troop_set_slot, "trp_province_array", ":slot", "$current_town"),
      (call_script, "script_legion_hq_set_banner", "$current_town",  13),
      (call_script, "script_troop_set_rank", "$temp_troop", slot_troop_legion, 13),#player legion
  (else_try),
      (eq, "$temp", 2),
      (troop_remove_gold, "trp_player", 50000),
      (troop_set_slot, "trp_players_aux_inf", 1, 1),##aux infacntry is created
      (assign, "$g_player_troop", "trp_players_aux_inf"),
      (display_log_message, "@You founded your own auxilia cohort!", color_good_news),
      (val_mul, ":relation_boost", 2),
      (val_div, ":relation_boost", 3),
      (call_script, "script_change_player_relation_with_troop", "$temp_troop", ":relation_boost"),
      (call_script, "script_troop_set_rank", "$temp_troop", slot_troop_aux, "pt_player_aux_inf"),#player inf
  (else_try),
      (eq, "$temp", 3),
      (troop_remove_gold, "trp_player", 40000),
      (troop_set_slot, "trp_players_aux_cav", 1, 1),##aux cav is created
      (assign, "$g_player_troop", "trp_players_aux_cav"),
      (display_log_message, "@You founded your own auxilia ala!", color_good_news),
      (val_div, ":relation_boost", 2),
      (call_script, "script_change_player_relation_with_troop", "$temp_troop", ":relation_boost"),
      (call_script, "script_troop_set_rank", "$temp_troop", slot_troop_aux, "pt_player_aux_cav"),#player cav
  (try_end),

  (call_script, "script_troop_set_title_according_to_faction", "$temp_troop", "$players_kingdom"),

  #SB : add a decent horse if none present
  (try_begin),
    (troop_slot_eq, "$temp_troop", dplmc_slot_upgrade_horse, 1),
    (troop_get_inventory_slot, ":cur_horse", "$temp_troop", ek_horse),
    (eq, ":cur_horse", -1),
    (store_random_in_range, ":item_no","itm_horse_1", "itm_steppe_horse_1"),
    (troop_set_inventory_slot, "$temp_troop", ek_horse, ":item_no"),
    (store_random_in_range, ":imod", imod_stubborn, imod_fresh),
    (troop_set_inventory_slot_modifier, "$temp_troop", ek_horse, ":imod"),
  (try_end),

  (troop_add_item, "$temp_troop", "itm_graves_simple_2"),
  (troop_add_item, "$temp_troop", "itm_roman_toga"),

  #SB : change troop base type (if player hasn't touched it already) after adding equipment
  (try_begin),
      (troop_get_class, ":class", "$temp_troop"),
      (eq, ":class", grc_infantry),
      (assign, ":slot_end", ek_head),
      (try_for_range, ":item_slot", ek_item_0, ":slot_end"),
          (troop_get_inventory_slot, ":item_no", "$temp_troop", ":item_slot"),
          (gt, ":item_no", -1),
          (item_get_type, ":itp", ":item_no"),
          (this_or_next|is_between, ":itp", itp_type_bow, itp_type_goods),
          (is_between, ":itp", itp_type_pistol, itp_type_bullets),
          (assign, ":class", grc_archers),
          (assign, ":slot_end", -1),
      (try_end),
      (try_begin),
          (troop_get_inventory_slot, ":cur_horse", "$temp_troop", ek_horse),
          (gt, ":cur_horse", -1),
          (assign, ":class", grc_cavalry),
      (try_end),
      (troop_set_class, "$temp_troop", ":class"),
  (try_end),

  (troop_set_auto_equip, "$temp_troop", 1), #dckplmc

  # (call_script, "script_create_kingdom_hero_party", "$temp_troop", "$current_town"),

  (assign, "$g_next_menu", "mnu_custom_unit_found"),
  (jump_to_menu, "mnu_customize_unit"),
  (finish_mission),
]],

