##train recruits
[anyone|plyr, "dplmc_constable_recruits_and_training",
[
(neg|is_between, "$g_constable_training_center", walled_centers_begin, walled_centers_end),
],
"Can you train some recruits, please?", "dplmc_constable_train_ask",
[]
],

[anyone, "dplmc_constable_train_ask",
[],
"Of course, where should I train them? Each day, money is taken from your private treasury and used to upgrade troops."
+" Additionally, training recruits will increase the total number of recruits available at the chosen town or fortress and add experience to the garrisoned troops."
+"^^Training works as follows: Your training skill determines how many troops in total can be upgraded. Then, your character level is taken into account."
+" If the troop level is higher than your character level, the troop cannot be upgraded."
+" If you have hired additional trainers (which is only possible if your faction's policy favors quality over quantity), your character level is further modified by adding 4.",
"dplmc_constable_train_select",[]],

[anyone|plyr|repeat_for_parties, "dplmc_constable_train_select",[
  (store_repeat_object, ":party_no"),
  (this_or_next|party_slot_eq, ":party_no", slot_party_type, spt_town),
  (party_slot_eq, ":party_no", slot_party_type, spt_castle),
  (party_slot_eq, ":party_no", slot_town_lord, "trp_player"),
  (str_store_party_name, s11, ":party_no"),
],
"{!}{s11}.", "dplmc_constable_train_type_ask",
[
(store_repeat_object, "$diplomacy_var"),
]
],

#SB : restructure dialogue
[anyone, "dplmc_constable_train_type_ask",
[
  (str_store_party_name, s11, "$diplomacy_var"),
],
"What type of units would you prefer me to train up in {s11}?", "dplmc_constable_train_type",
[]
],

[anyone|plyr, "dplmc_constable_train_type",
[],
"Never mind.", "dplmc_constable_pretalk",
[]
],
