[trp_legatus_12|plyr, "lord_talk_ask_something_2", [
  #(eq, "$g_is_emperor", 1),
  (neg|check_quest_active, "qst_important_friends"), # not active
  (quest_slot_ge, "qst_important_friends", slot_quest_current_state, 1), # but
  (quest_slot_eq, "qst_important_friends", slot_quest_temp_slot, 0),
],
"I always wondered why you became a Christian.",
"kaeso_christ_talk_1", [
  (quest_set_slot, "qst_important_friends", slot_quest_temp_slot, 1),
]],

[anyone, "kaeso_christ_talk_1", [
],
"One day I met a man called Petrus. He is one of the Apostles. I was riding from the Castra praetoria to the Palatine. Caesar called me; I should come as fast as possible. Next to the street, I saw this poor man dressed in rags, trying to treat a lethal wound of a woman. As he saw me approaching, he ran onto the street and tried to stop us. I was actually confused, as the poor usually fear us Praetorians. But without any fear, he shouted that he needs help, otherwise the woman will die. I am not sure why, but I stopped my horse. I ordered a slave to call for a physician while I tried to help him.", "kaeso_christ_talk_2", []],

[anyone, "kaeso_christ_talk_2", [
],
"The woman had a severe wound on her chest. The man told me she was stabbed with a pugio by her cruel husband. We tried our best to stop the bleeding. The slave returned with a physician, and he treated her wounds. She survived. I was confused and asked him why he called me for help, as the plebs usually fear the rich and would never dare such actions. He said: 'Why did you stop and help me?' And I answered that I didn't know. I just was impressed and confused by his boldness.", "kaeso_christ_talk_3", []],

[anyone, "kaeso_christ_talk_3", [
],
"He then told me that his name is Petrus, one of the Apostles of Christus. He then told me that if you meet the world with love, you will also receive love. This is why he knew I would help him. I was impressed and wanted to learn more about his faith. He invited me to eat with him at his house. Although I knew I would violate Caesar's orders, I followed his invitation. Although his house is poor and simple, although he has not much food to share with me, we enjoyed a good meal together.", "kaeso_christ_talk_4", []],

[anyone, "kaeso_christ_talk_4", [
],
"Although Caesar was angry about me, I didn't fear his wrath, like many others do. I know now that there is something deeper, something better than all the pleasures a Caesar like Nero has: It is the love of God. I met Petrus several times, and he introduced me to the Christian faith. He told me what happened with Christus and all the other wonders that happened due to God. Finally, he baptized me in the river of Tiber. Since that day, I am a Christian.", "kaeso_christ_talk_5", []],

[anyone|plyr, "kaeso_christ_talk_5", [
],
"Interesting, but I was told that being a Christian means to forgive, even your enemies. And it forbids killing. It is, for me, a contradiction that the Praefect of the Praetorian guard follows such a faith.", "kaeso_christ_talk_6", []],

[anyone, "kaeso_christ_talk_6", [
],
"I know that I have done many sins, especially due to the cruel orders of Nero. But I confessed all my sins. And since I am a Christian, I tried my best to avoid any bloodshed if possible. And I hope God will forgive me.", "kaeso_christ_talk_7", []],

[anyone|plyr, "kaeso_christ_talk_7", [
],
"I will never understand you Christians.", "lord_pretalk", []],
[anyone|plyr, "kaeso_christ_talk_7", [
],
"Thank you. It was very enlightening.", "lord_pretalk", []],

#join
[anyone|plyr,"lord_talk_ask_something_2",[
  (store_current_hours, ":current_hours"),
  (val_sub, ":current_hours", 24 * 4),
  (ge, ":current_hours", "$g_last_affiliate_attempt"),

  (ge, "$g_talk_troop_faction_relation", 0),
  (neg|troop_slot_ge, "$g_talk_troop", slot_troop_prisoner_of_party, 0),
  (eq, "$players_kingdom", "$g_talk_troop_faction"),
  (eq, "$player_has_homage", 1),
  ##diplomacy start+
  #(eq, "$g_player_affiliated_troop", 0),
  (lt, "$g_player_affiliated_troop", 1),
  ##diplomacy end+
  (troop_slot_eq, "$g_talk_troop", dplmc_slot_troop_affiliated, 0),
  (call_script, "script_troop_get_player_relation", "$g_talk_troop"),
  (gt, reg0, 0),
  (call_script, "script_troop_get_family_relation_to_troop", "trp_player", "$g_talk_troop"),
  (le, reg0, 0),
],
"I have great respect for your lineage, I wish to be affiliated to your family.", "dplmc_lord_family_affiliate",[]],

[anyone, "dplmc_lord_family_affiliate",[
  (str_clear, s10),
  (assign, ":approved", 0),
  (troop_get_slot, ":lord_renown", "$g_talk_troop", slot_troop_renown),
  (try_begin),
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
    (troop_get_slot, ":player_renown", "trp_player", slot_troop_renown),
    (try_begin),
      (ge, ":player_renown", ":lord_renown"),
      (str_store_string, s10, "@You have shown great strength on the battlefield. But why should I enlist you within us?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    ##diplomacy start+ Add support for additional types
    (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_ambitious),
    ##diplomacy end+
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_cunning),
    (assign, ":has_center", 0),
    (try_for_range, ":center_no", centers_begin, centers_end),
      (this_or_next|party_slot_eq, ":center_no", slot_party_type, spt_town),
      (party_slot_eq, ":center_no", slot_party_type, spt_castle),
      (party_slot_eq, ":center_no", slot_town_lord, "trp_player"),
      (assign, ":has_center", 1),
    (try_end),
    (try_begin),
      (eq, ":has_center", 1),
      (str_store_string, s10, "@All of life is about pros and cons. Why would we allow you to be our fellow?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_debauched),
    (try_begin),
      (le, "$player_honor", -10),
      (str_store_string, s10, "@I know, people do fear your harshness. Should we though?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    ##diplomacy start+ Add support for additional types
    (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
    ##diplomacy end+
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_upstanding),
    (try_begin),
      (ge, "$player_honor", 10),
      (str_store_string, s10, "@Indeed, I have heard of your loyalty and valor. But is it enough to join us?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    ##diplomacy start+ Add support for additional types
    (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
    ##diplomacy end+
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
    (try_begin),
      (ge, "$g_talk_troop_faction_relation", 60),
      (str_store_string, s10, "@I'm glad you want to support us. But, would it be wise for you, to affiliate to our family?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_selfrighteous),
    (try_begin),
      (store_troop_gold, ":wealth", "trp_household_possessions"),
      (store_troop_gold, ":cash", "trp_player"),
      (val_add, ":wealth", ":cash"),
      (val_sub, ":wealth", "$g_player_debt_to_party_members"),

      (val_mul, ":lord_renown", 65),
      (ge, ":wealth", ":lord_renown"),

      (str_store_string, s10, "@Beside your wealth, how could you possibly serve me and my family?"),
      (assign, ":approved", 1),
    (try_end),
  (else_try),
    (try_begin),
      (call_script, "script_troop_get_player_relation", "$g_talk_troop"),
      (gt, reg0, 75),
      ##diplomacy start+ Reworded
      #(str_store_string, s10, "@My friend, I see you reasoning. But would you really risk our friendship on partnership?"),
      (str_store_string, s10, "@My friend, I see your reasoning. But would you really risk straining our friendship by entering into a formal partnership?"),
      ##diplomacy end+
      (assign, ":approved", 1),
    (try_end),
  (try_end),
  (eq, ":approved", 1),
],
"{!}{s10}", "dplmc_lord_family_affiliate_response",[]],

