[anyone|plyr,"otho_main_story_2",[
 ],
    "Is that any way to speak to a friend?",
  "otho_main_story_3",[]],
[anyone,"otho_main_story_3",[
 ],
    "Forgive me, but I have a great distaste for such affairs, I don't like this even though I haven't heard what you want to tell me.",
  "otho_main_story_4",[]],
[anyone|plyr,"otho_main_story_4",[
 ],
    "Have I ever disappointed you so far?",
  "otho_main_story_5",[]],
