[anyone|plyr ,"lord_invite_1_nero",[],  "Thank you {s65}, you honour me with your offer.", "lord_invite_2_nero",[]],

[anyone|plyr ,"lord_invite_1",[],  "Thank you, {s65}, you honour me with your offer.", "lord_invite_2",[]],
