[anyone|plyr, "mayor_talk",[
  (eq, "$current_town", "p_town_48"),
  (check_quest_active, "qst_become_pharao"),
  (quest_slot_ge, "qst_become_pharao", slot_quest_current_state, 2),
],"I am ready for my next Pharaoh ceremony.",
"mayor_talk_cermoney_1",[]],

[anyone, "mayor_talk_cermoney_1",[
  (quest_slot_ge, "qst_become_pharao", slot_quest_dont_give_again_remaining_days, 1),
],"Forgive me, my lord, but the people are still recovering from the last festival. We need more time to prepare.",
"mayor_pretalk",[]],

[anyone, "mayor_talk_cermoney_1",[],
"Excellent! The next lavish festival will cost 75,000 denarii. Should I go ahead with preparations?",
"mayor_talk_cermoney_2",[]],

[anyone|plyr, "mayor_talk_cermoney_2",[
  (store_troop_gold, ":g", "trp_player"),
  (ge, ":g", 75000),
],"Yes. (75,000 denarii)",
"mayor_talk_cermoney_3",[
  (troop_remove_gold, "trp_player", 75000),
]],

[anyone, "mayor_talk_cermoney_3",[],
"Excellent, I will make all preparations.",
"close_window",[
  (quest_set_slot, "qst_become_pharao", slot_quest_dont_give_again_remaining_days, 2),
  (jump_to_menu, "mnu_pharaoh_event_4"),
  (finish_mission),
]],

[anyone|plyr, "mayor_talk_cermoney_2",[],"On second thought, no.",
"mayor_pretalk",[]],

[anyone|plyr, "mayor_talk",[
  (eq, "$g_is_emperor", 0),
  (check_quest_active, "qst_become_pharao"),
  (quest_slot_eq, "qst_become_pharao", slot_quest_current_state, 1),
  (eq, "$current_town", "p_town_48"),
  (str_store_faction_name, s25, "$players_kingdom"),
],"I am king of {s25}, and thus the Pharaoh of Egypt!",
"mayor_talk_pharaoh",[]],

[anyone|plyr, "mayor_talk",[
  (ge, "$g_is_emperor", 1),
  (check_quest_active, "qst_become_pharao"),
  (quest_slot_eq, "qst_become_pharao", slot_quest_current_state, 1),
  (eq, "$current_town", "p_town_48"),
],"I am Caesar Augustus, Princeps of Rome, and thus the Pharaoh of Egypt!",
"mayor_talk_pharaoh",[]],

[anyone, "mayor_talk_pharaoh",[
],"Of course, oh Caesar. Nobody can argue the throne is not rightfully yours. ^^However... the ancient tradition dictates that one must undergo a number of ceremonies and rites, accompanied by long lavish festivals. Only then can one wear the double crown of Egypt and be a true Pharaoh.",
"mayor_talk_pharaoh_2",[]],

[anyone|plyr, "mayor_talk_pharaoh_2",[],"What ceremonies?",
"mayor_talk_pharaoh_3",[]],

[anyone, "mayor_talk_pharaoh_3",[
],"There are 5 main ceremonies. The transition often lasts up to a year and, of course, there's the matter of cost... ^^It will look best if you pay for it personally, but we can put the burden on the Egyptian nobility if you prefer. ^^You will get the most admiration if you carefully go through each ceremony, but we can try to combine and shorten the process at the risk of offending some.",
 "mayor_talk_pharaoh_4",[]],

[anyone|plyr, "mayor_talk_pharaoh_4",[],"Screw your ceremonies! I will wear the crown today and appear before the people.",
"mayor_talk_pharaoh_reaction_1",[]],

[anyone, "mayor_talk_pharaoh_reaction_1",[],"As you wish ...", "close_window",[
  (troop_set_slot, "trp_global_variables", g_lord_event_possible, 1),##to avoid event spawn
  (jump_to_menu, "mnu_pharaoh_event_1"),
  (finish_mission),
]],

[anyone|plyr, "mayor_talk_pharaoh_4",[
  (store_troop_gold, ":g", "trp_player"),
  (ge, ":g", 150000),
],"Make it one grand ceremony. I will pay for it. (150,000 denarii)",
"mayor_talk_pharaoh_reaction_2",[]],

[anyone, "mayor_talk_pharaoh_reaction_2",[
],"As you wish!!", "close_window",[
  (troop_set_slot, "trp_global_variables", g_lord_event_possible, 1),##to avoid event spawn
  (troop_remove_gold, "trp_player", 150000),
  (jump_to_menu, "mnu_pharaoh_event_2"),
  (finish_mission),
]],

[anyone|plyr, "mayor_talk_pharaoh_4",[
],"Make it one grand ceremony. Egypt will pay for it.",
"mayor_talk_pharaoh_reaction_3",[]],

[anyone, "mayor_talk_pharaoh_reaction_3",[
],"As you wish.", "close_window",[
  (troop_set_slot, "trp_global_variables", g_lord_event_possible, 1),##to avoid event spawn
  (jump_to_menu, "mnu_pharaoh_event_3"),
  (finish_mission),
]],

[anyone|plyr, "mayor_talk_pharaoh_4",[
],"I spare no expense! Hold many lavish festivals for the people of Egypt adhering to every tradition.",
"mayor_talk_pharaoh_reaction_4",[]],

[anyone, "mayor_talk_pharaoh_reaction_4",[
  (eq, "$g_is_emperor", 1),
],"That is wonderful news, oh Caesar! Your respect for traditions will surely be appreciated, and a series of many celebrations will strengthen the memory of your divinity. ^^Please talk to me again when you are ready for the first ceremony.",
"close_window",[
  (quest_set_slot, "qst_become_pharao", slot_quest_current_state, 2),
  (str_store_party_name_link, s25, "p_town_48"),
  (add_quest_note_from_sreg, "qst_become_pharao", 7, "@Once you are ready speak to the magistrate civium of {s25} to initiate the next stage of your coronation ceremony.", 0),
]],
[anyone, "mayor_talk_pharaoh_reaction_4",[],"Great, my king! Your respect for traditions will surely be appreciated and a series of many celebrations will strengthen the memory of your rule.^^Please talk to me again when you are ready for the first ceremony.",
"close_window",[
  (quest_set_slot, "qst_become_pharao", slot_quest_current_state, 2),
  (str_store_party_name_link, s25, "p_town_48"),
  (add_quest_note_from_sreg, "qst_become_pharao", 7, "@Once you are ready speak to the magistrate civium of {s25} to initiate the next stage of your coronation ceremony.", 0),
]],

