[anyone|plyr,"merchant_quest_about_job_2",[], "Well, I'm still working on it.", "merchant_quest_about_job_working",[]],
[anyone,"merchant_quest_about_job_working",[], "Good. I'm sure you will handle it.", "mayor_pretalk",[]],

