[trp_amorus, "start",[
  (eq, "$talk_context", tc_campaign_talk),
],"Ave. Are you here to see the widow, Lucia Sabina?",
"amorus_talk",
[]],
[anyone|plyr, "amorus_talk",[],"I am. And who are you?", "amorus_talk_2",[]],
[anyone|plyr, "amorus_talk",[],"That is none of your concern.", "amorus_talk_2",[]],

[anyone, "amorus_talk_2",[],"Stay away from her! She belongs to me! If I see you near her villa again, there will be serious trouble!", "amorus_talk_3",[]],

[anyone|plyr, "amorus_talk_3",[],"And who are you to give me orders?", "amorus_talk_4",[]],

[anyone, "amorus_talk_4",[],"I am Amorus Valentinus, son of the Senator Lucratius Valentinus. My father is an influential man. I can make your life very difficult.", "amorus_talk_5",[]],
[anyone|plyr, "amorus_talk_5",[],"You're the biggest fool in Rome!", "amorus_talk_6",[]],
[anyone|plyr, "amorus_talk_5",[],"I've met smarter paving stones.", "amorus_talk_6",[]],
[anyone|plyr, "amorus_talk_5",[],"Very well. I will stay away from her.", "amorus_talk_6_never",[]],

[anyone, "amorus_talk_6_never",[],"A wise decision. Now get out of my sight, plebeian.", "amorus_talk_6_never2",[]],
[anyone|plyr, "amorus_talk_6_never2",[],"Watch your tone, boy.", "amorus_talk_6_1",[]],
[anyone|plyr, "amorus_talk_6_never2",[],"As you say.", "close_window",[
  (jump_to_menu, "mnu_town"),
  (call_script, "script_fail_quest", "qst_widow"),
  (call_script, "script_end_quest", "qst_widow"),
]],

[anyone, "amorus_talk_6",[],"What did you call me?! You insolent bastard! Apologize at once, or I'll see you flogged!",
"amorus_talk_7",[]],
[anyone, "amorus_talk_6_1",[],"What was that? Did you just threaten me?",
"amorus_talk_7",[]],

[anyone|plyr, "amorus_talk_7",[],"You heard me. Now crawl back to whatever hole you came from and stay away from Lucia Sabina.",
"amorus_talk_8",[]],

[anyone, "amorus_talk_8",[],"No one speaks to me like that! I'll tell my father! You'll be ruined!",
"amorus_talk_9",[]],

[anyone|plyr, "amorus_talk_9",[],"-- You draw your pugio and press it to his throat. --^^Say one more word, and it will be your last. Now, listen. You will never bother Lucia Sabina again. You will not even walk down this street again. Do you understand me?",
"amorus_talk_10",[]],

[anyone, "amorus_talk_10",[],"Yes! Yes, anything you say! Please, just don't kill me!",
"amorus_talk_11",[]],

[anyone|plyr, "amorus_talk_11",[],"Hah. Pathetic. Now get out of here before I change my mind.",
"amorus_talk_12",[]],
[anyone|plyr, "amorus_talk_11",[],"Leave now.",
"amorus_talk_12",[]],

[anyone, "amorus_talk_12",[],"I swear, I'm gone! You'll never see me again!",
"close_window",[
  (display_message, "str_quest_updated", message_alert),
  (add_quest_note_from_sreg, "qst_widow", 3, "@Amorus Valentinus isn't a problem anymore.", 0),
  (jump_to_menu, "mnu_lucias_house_2")
]],

[trp_petronius, "start",
[
  (check_quest_active, "qst_blank_quest_8"),
  (neq, "$talk_context", tc_campaign_talk),
 ],
  "Ave, what do you want?", "petron_talk33",
[]],
[trp_petronius, "start",
[
  (eq, "$talk_context", tc_campaign_talk),
 ],
  "Ave friend. You watched the spectacle too? This world is full of cruelty. What a shame that honorable people are murdered in such a way. But there is hope for this dark world.\
 You must know, I am part of the Christian community and we are always looking for new people, especially poor people like you. People who have enough from this suffering.", "petron_talk_new",
[]],

[anyone|plyr, "petron_talk_new",[],"Yes it is true. This world seems dark to me.", "petron_talk_new_2",[]],
[anyone|plyr, "petron_talk_new",[],"I would prefer if you would leave me alone.", "petron_talk_new_2_1",[]],
[anyone|plyr, "petron_talk_new",[],"Away with you, beggar!", "petron_talk_new_2_1",[]],

[anyone, "petron_talk_new_2",[],"Very good. I think it would be the best for you if you would join our community. You should know that we help the poor people of Rome.", "petron_talk_new_3",[]],

[anyone|plyr, "petron_talk_new_3",[],"Sounds interesting.", "petron_talk_new_4",[]],
[anyone|plyr, "petron_talk_new_3",[],"No, I must refuse.", "petron_talk_new_3_1",[]],
[anyone, "petron_talk_new_3_1",[],"If you ever have interest, you can find me in the streets of Rome.", "close_window",[(jump_to_menu, "mnu_auto_return")]],

[anyone, "petron_talk_new_2_1",[],"Very well, I only wanted to inform you about our small community of truth seekers, who help the poor of Rome to alleviate their suffering.\
 If you have ever interest in joining our community, you can find me in the streets of Rome.", "petron_talk_new_2_2",[]],
[anyone|plyr, "petron_talk_new_2_2",[],"Wait. Please, tell me more.", "petron_talk_new_4",[]],
[anyone|plyr, "petron_talk_new_2_2",[],"So, then farewell.", "close_window",[(jump_to_menu, "mnu_auto_return")]],

[anyone, "petron_talk_new_4",[],
"Very good. But, we should continue our conversation somewhere else. Come with me. ^^(Something forces you to follow him.)",
"close_window",[
  (setup_quest_text,"qst_blank_quest_8"),
  (str_store_string, s2, "@Those strangers look interesting. Maybe they are useful to get some money. (To visit them, talk with Petronius, who can be found in the streets of Rome.)"),
  (call_script, "script_start_quest", "qst_blank_quest_8", "$g_talk_troop"),
  (quest_set_slot, "qst_blank_quest_8", slot_quest_temp_slot, 1),
  (jump_to_menu, "mnu_continue"),
]],

