[anyone|plyr, "olympia_talk_horse_race_2",[], "Wait a second. I think I should train more.", "organiser_pretalk",[]],

[anyone|plyr, "organiser_talk",[], "Tell me more about Olympia.", "olympia_talk",[]],

[anyone, "olympia_talk",[], "The dactyl Heracles and four of his brothers, Paeonaeus, Epimedes, Iasius and Idas, raced at Olympia to entertain the newborn Zeus. The dactyls are a race, it is not Heracles, the son of Zeus! Anyway. He crowned the victor with an olive tree wreath, which thus became a peace symbol, \
  which also explains the four year interval. The other Olympian gods, so named because they lived permanently on Mount Olympus, would also engage in wrestling, jumping and running contests. That's way we now celebrate the Olympic games here.", "organiser_pretalk",[]],

[anyone|plyr, "organiser_talk",[], "Tell me more about the Zeus statue.", "olympia_talk_zeus",[]],
[anyone, "olympia_talk_zeus",[], "The Statue of Zeus is a giant seated figure, about 43 feet tall, it was made by the sculptor Phidias around many centuries ago at the sanctuary of Olympia and erected in the Temple of Zeus there. The sculpture is made of ivory plates and gold panels over a wooden framework and it representes the god Zeus sitting on an elaborate cedar wood throne ornamented with ebony, ivory, gold and precious stones.", "organiser_pretalk",[]],

[anyone|plyr, "organiser_talk",[], "When will be the next games?", "olympia_2_talk",[]],
[anyone|plyr, "organiser_talk",[(eq, "$nero_events", 5),], "Is it true that Nero has won the Olympic Games?", "olympia_2_talk_about_bero",[]],
[anyone, "olympia_2_talk_about_bero",[], "Of course it is true! But he had not won through talent. He had effectively stifled true competition and seems to have been oblivious of reality.", "organiser_pretalk",[]],

[anyone, "olympia_2_talk",[
  (quest_get_slot,reg24, "qst_olympic_games", slot_quest_dont_give_again_remaining_days),
 ], "In {reg24} days! In the mean time you can train all different competitions here together with other famous athlets.", "organiser_pretalk",[]],
[anyone|plyr, "organiser_talk",[], "Can I take part?", "olympia_2_talk_44",[]],
[anyone, "olympia_2_talk_44",[], "Of course you can, but you should train a lot, it is a hard competition.", "olympia_talky_walky",[]],
[anyone|plyr, "olympia_talky_walky",[(eq, "$g_is_emperor", 1)], "Of course I will win, I am a Caesar!", "organiser_pretalk",[]],
[anyone|plyr, "olympia_talky_walky",[], "Maybe I have luck.", "organiser_pretalk",[]],
[anyone|plyr, "organiser_talk",[], "Ave atque vale!", "close_window",[]],
##End Olympia talk

##lord talk feast at villa start.
## villa feast talk
[anyone,"start",[
  (troop_slot_eq, "$g_talk_troop", slot_troop_occupation, slto_kingdom_hero),
  (eq, "$talk_context", tc_feast),

  (try_begin),
      # This is the FIRST time the player talks to this lord at the feast.
      (ge, "$g_time_since_last_talk", 24),

      (call_script, "script_get_household_modifier", household_mod_cook_quality),
      (store_add, ":cooking_level", 5, reg0),
      (call_script, "script_describe_cook_quality_to_s1", ":cooking_level", 3),
      (str_store_string_reg, s18, s1),

      (try_begin),
          (gt, "$g_talk_troop_relation", 50),
          (str_store_string, s20, "@My dearest {playername}! It brings me great joy to be in your home. This feast is a testament to your generosity and good taste!^And for the meal ... {s18}"),
      (else_try),
          (gt, "$g_talk_troop_relation", 20),
          (str_store_string, s20, "@It is a genuine pleasure to attend, {playername}. You have my sincerest thanks for the invitation.^And for the meal ... {s18}"),
      (else_try),
          (gt, "$g_talk_troop_relation", 0),
          (str_store_string, s20, "@Thank you for your hospitality, {playername}. This is a fine gathering.^And for the meal ... {s18}"),
      (else_try),
          (gt, "$g_talk_troop_relation", -20),
          (str_store_string, s20, "@Your invitation was received, {playername}. I am here, as you can see.^And for the meal ... {s18}"),
      (else_try),
          (str_store_string, s20, "@Let us be clear, {playername}. I attend this... function out of obligation, not desire.^And for the meal ... {s18}"),
      (try_end),
  (else_try),
      # This is for any SUBSEQUENT conversation with the lord during the same feast.
      (try_begin),
          (gt, "$g_talk_troop_relation", 50),
          (str_store_string, s20, "@Come, my friend! Join me. The wine is excellent, and the company even better now that you are here!"),
      (else_try),
          (gt, "$g_talk_troop_relation", 20),
          (str_store_string, s20, "@Ah, {playername}. I was hoping we might have a moment to speak. Is there something on your mind?"),
      (else_try),
          (gt, "$g_talk_troop_relation", 0),
          (str_store_string, s20, "@Yes, {playername}? Is there something you require?"),
      (else_try),
          (gt, "$g_talk_troop_relation", -20),
          (str_store_string, s20, "@What is it? As you can see, I am engaged in conversation."),
      (else_try),
          (str_store_string, s20, "@State your business quickly. My patience is not as plentiful as your wine."),
      (try_end),
  (try_end),
], "{s20}", "lord_talk",[]],

