[trp_hadrianus,"start",[
  (quest_slot_ge, "qst_wlodowiecus_adventure_1", slot_quest_current_state, 6),
  (quest_slot_eq, "qst_hadrian_letter", slot_quest_current_state, 0),
],"--He seems to be lost in thought. Then he notice you.--^^Ah {playername}. Good to see you again. What leads you to me today?", "hadrian_quest_talk",[]],

[anyone|plyr,"hadrian_quest_talk",[], "I just wanted to visit you again and see how things developed for you.", "hadrian_quest_talk2",[]],
[anyone,"hadrian_quest_talk2",[], "Ah very nice. I expended my business with the money I earned from selling the spice and now I am trading with Hellenic armours and weapons. Though I was thinking about my family recently. It is so long ago since I last saw them. Even though I don't have the best memories of them, I would still like to know what happened to them and maybe send them some money if they are impoverished. However, I cannot leave Rome at the moment because of my business.", "hadrian_quest_talk3",[]],

[anyone|plyr,"hadrian_quest_talk3",[], "I can travel to your home village and take a look for you.", "hadrian_quest_talk4",[]],

[anyone,"hadrian_quest_talk4",[], "Perfect! My home is near {s22}. You best ask the local leader about them. My father's name is Albmariz, son of Sigmariz. My mothers name is Sigrada, daughter of Haderic.", "close_window",[
  (str_store_party_name_link, s23, "p_village_222"),
  (str_store_party_name, s22, "p_village_222"),
  (quest_set_slot, "qst_hadrian_letter", slot_quest_current_state, 1),
  (setup_quest_text,"qst_hadrian_letter"),
  (str_store_string, s2, "@Hadrianus asked you to travel to {s23} and find more out about his family."),
  (call_script, "script_start_quest", "qst_hadrian_letter", "trp_hadrianus"),
]],

[trp_hadrianus,"start",[
  (neg|check_quest_active, "qst_wlodowiecus_adventure_4"),
  (quest_slot_ge, "qst_wlodowiecus_adventure_4", slot_quest_current_state, 13),
  (quest_slot_eq, "qst_wlodowiecus_adventure_4", slot_quest_target_item, 0),
],"Greetings, {playername}. I hope you are doing well. Unfortunately, Phamanus's caravan business has not been as profitable as I had hoped. The trade routes are far more dangerous than we anticipated, and the rival merchants already operating there are doing everything they can to sabotage our efforts."
+" Lei Li's business is also facing difficulties. The plan was to collaborate with Phamanus on the Silk Road, but a great war has broken out in Seres, disrupting our operations!"
+" That Xiongnu king, Temur, he is attacking Seres now!",
"hadrian_wlod_4_recap",[
  (quest_set_slot, "qst_wlodowiecus_adventure_4", slot_quest_target_item, 1),
]],

